"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "italic",
  "line": [
    [
      [
        "M",
        19,
        4
      ],
      [
        "L",
        10,
        4
      ]
    ],
    [
      [
        "M",
        14,
        20
      ],
      [
        "L",
        5,
        20
      ]
    ],
    [
      [
        "M",
        15,
        4
      ],
      [
        "L",
        9,
        20
      ]
    ]
  ]
}

function SignItalicWords(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="words" {...props} />
}

export { SignItalicWords, shape }
